package messagequeue
import("testing";"time";"strings")
func TestQAFoundationReceiptGenerationIsolation(t *testing.T){s,b:=humanFixture(t);humanReserve(t,s,b,"a","");other:=b;other.Generation=99;r,e:=s.ReadHumanOperation(other,"reserve_a","");if e==nil&&r.Status=="committed"{t.Fatalf("old-generation receipt disclosed: binding=%+v",r.Input.Binding)}}
func TestQAFoundationMoveCannotCrossRunning(t *testing.T){s,b:=humanFixture(t);a:=humanReserve(t,s,b,"a","");humanReserve(t,s,b,"b","a");if _,_,e:=s.Enqueue(humanSealEntry(a));e!=nil{t.Fatal(e)};if _,_,e:=s.Transition(b.Session,"a",[]State{Queued},Running,"","","");e!=nil{t.Fatal(e)};rev,m,_:=s.HumanMembership(b);r,e:=s.HumanApply(b,HumanOperation{ID:"move_b",Kind:"move",Request:"b",ExpectedRevision:1,Relative:"a",Placement:"before",QueueRevision:&rev,MembershipHash:m},"boot",time.Now());if e==nil&&r.Status=="committed"{t.Fatalf("moved across running barrier: %+v",r)}}
func TestQAFoundationOperationBindingConflict(t *testing.T){s,b:=humanFixture(t);humanReserve(t,s,b,"a","");other:=b;other.Generation=99;op:=HumanOperation{ID:"reserve_a",Kind:"reserve",Request:"a",Content:"a",IntentHash:strings.Repeat("a",64),Assets:[]byte(`[]`)};r,e:=s.HumanApply(other,op,"boot",time.Now());if e==nil&&r.Status=="committed"{t.Fatalf("new binding reused old committed operation: %+v",r.Input.Binding)}}
